using Backend.Exceptions;using Backend.Models;using Backend.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace Backend.Controllers;[ApiController][Route("api/[controller]")][Authorize(Roles = "RH")]public class PermisoController : ControllerBase{    private readonly PermisoService _permisoService;    public PermisoController(PermisoService permisoService)    {        _permisoService = permisoService;    }    [HttpGet]    public async Task<IActionResult> ObtenerTodos([FromQuery] int skip = 0, [FromQuery] int take = 100)    {        var permisos = await _permisoService.GetPermisosAsync(skip, take);        return Ok(permisos);    }    [HttpGet("{id}")]    public async Task<IActionResult> ObtenerPorId(long id)    {        var permiso = await _permisoService.GetPermisoByIdAsync(id);        if (permiso is null)            return NotFound(new { mensaje = $"No se encontró el permiso con Id {id}." });        return Ok(permiso);    }    [HttpPost]    public async Task<IActionResult> Crear([FromBody] CrearPermisoModel model)    {        try        {            var permiso = await _permisoService.CreatePermisoAsync(model);            return CreatedAtAction(                nameof(ObtenerPorId),                new { id = permiso.Id },                permiso);        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpPut("{id}")]    public async Task<IActionResult> Actualizar(long id, [FromBody] ActualizarPermisoModel model)    {        try        {            var actualizado = await _permisoService.UpdatePermisoAsync(id, model);            if (!actualizado)                return NotFound(new { mensaje = $"No se encontró el permiso con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpDelete("{id}")]    public async Task<IActionResult> Eliminar(long id)    {        try        {            var eliminado = await _permisoService.DeletePermisoAsync(id);            if (!eliminado)                return NotFound(new { mensaje = $"No se encontró el permiso con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }}